using Microsoft.EntityFrameworkCore;using SmartFarm.Repositories;using SmartFarm.Repositories.Data;using SmartFarm.Repositories.Entities;using SmartFarm.Services;using SmartFarm.Services.Models;using SmartFarm.Services.Services;using Xunit;
namespace SmartFarm.Repositories.Tests;
public class UserManagementServiceTests
{private static AppDbContext Context()=>new(new DbContextOptionsBuilder<AppDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options);
[Fact]public async Task Admin_can_create_staff_and_update_profile(){await using var db=Context();var service=new UserService(new UnitOfWork(db));var created=await service.CreateStaffAsync(new("Staff.New@Test.Local","New Staff","Password@123","0901234567","Farm"));Assert.Equal(RoleNames.Staff,created.Role);Assert.True(created.EmailConfirmed);Assert.Equal("staff.new@test.local",created.Email);var updated=await service.UpdateProfileAsync(created.UserId,new("Updated Staff","0911111111","New address"));Assert.Equal("Updated Staff",updated.FullName);Assert.True(PasswordHasher.Verify("Password@123",(await db.Users.FindAsync(created.UserId))!.PasswordHash));}
[Fact]public async Task Duplicate_staff_email_is_rejected(){await using var db=Context();db.Add(new User{Email="staff@test.local",FullName="S",PasswordHash="x"});await db.SaveChangesAsync();var service=new UserService(new UnitOfWork(db));var error=await Assert.ThrowsAsync<AppException>(()=>service.CreateStaffAsync(new("STAFF@test.local","Other","Password@123",null,null)));Assert.Equal(409,error.StatusCode);}
[Fact]public async Task User_detail_includes_avatar_url(){await using var db=Context();var user=new User{Email="ava@test.local",FullName="Ava",PasswordHash="x",Role=RoleNames.Customer,AvatarUrl="https://cdn.example/a.png"};db.Add(user);await db.SaveChangesAsync();var service=new UserService(new UnitOfWork(db));var dto=await service.DetailAsync(user.UserId);Assert.Equal("https://cdn.example/a.png",dto.AvatarUrl);}
[Fact]public async Task Updating_user_sets_updated_at_automatically(){await using var db=Context();var user=new User{Email="upd@test.local",FullName="Old",PasswordHash="x",Role=RoleNames.Customer};db.Add(user);await db.SaveChangesAsync();Assert.Null(user.UpdatedAt);var service=new UserService(new UnitOfWork(db));var updated=await service.UpdateProfileAsync(user.UserId,new("New Name","0911111111","Addr"));Assert.NotNull(updated.UpdatedAt);Assert.NotNull((await db.Users.FindAsync(user.UserId))!.UpdatedAt);}}
